      id: p.id, name: p.name, color: p.color, connected: p.connected, host: p.id === g.hostId,
      score: p.score, fooled: p.fooled, truths: p.truths, likes: p.likes,
      wrote: g.phase === 'write' ? !!g.lies[p.id] : undefined,
